INSERT INTO wellness_activities (element, internal_name, internal_tradition, internal_how_to, internal_research, external_name, external_category, external_how_to, external_research, combo_routine, best_time, time_reason) VALUES
  ('Fire', 'Kapalabhati (ลมไฟ)', 'โยคะ/Pranayama', 'หายใจออกแรงๆ เร็วๆ ทางจมูก ปล่อยให้หายใจเข้าเป็นไปเอง ทำต่อเนื่อง 20-30 ครั้งต่อรอบ', 'Nivethitha et al. 2017, Ancient Science of Life', 'วิ่ง หรือ ปีนเขา/hiking ระดับหนัก', 'movement', 'เคลื่อนไหวต่อเนื่อง 20-30 นาที ให้หัวใจเต้นเร็วขึ้นชัดเจน', 'Niedermeier et al. — hiking 30 นาที ลดฮอร์โมนความเครียดได้ถึง 28%', 'ตอนเช้า: Kapalabhati 5 นาทีก่อนออกจากบ้าน แล้วตามด้วยวิ่ง/เดินเร็ว 20 นาที — ใช้จังหวะหายใจที่กระตุ้นแล้วต่อด้วยการเคลื่อนไหวจริง', 'เช้า', 'ออกกำลังกายตอนเช้าช่วย advance circadian phase และลดคอร์ติซอลตอนตื่นในระยะยาว (PMC systematic review)'),
  ('Water', 'Bhramari (หายใจผึ้ง)', 'โยคะ/Pranayama', 'หายใจเข้าลึกๆ หายใจออกพร้อมทำเสียงฮัมต่อเนื่อง ทำ 5-10 รอบ', 'ลด cortisol, calming (เชื่อมกับ Nivethitha et al. 2017)', 'เดินเบาๆในธรรมชาติ / ฟังเพลงบรรเลงสงบ', 'nature/music', 'เดินช้าๆ 15-20 นาทีในที่มีต้นไม้ หรือฟังเพลงบรรเลงแบบตั้งใจฟัง (ไม่ใช่เปิดคลอ)', 'Bratman/Stanford — เดินธรรมชาติลดการทำงาน subgenual PFC (จุดคิดวนซ้ำ)', 'ก่อนนอน: Bhramari 5 รอบบนเตียง แล้วฟังเพลงบรรเลงเบาๆ 10 นาทีก่อนหลับ', 'ก่อนนอน', 'งานวิจัยชัดเจนว่ากิจกรรมสงบก่อนนอนช่วยการนอนหลับ ต่างจากออกกำลังกายหนักที่รบกวนการนอน'),
  ('Earth', 'Dan Tian breathing (หายใจจากจุดต่ำท้อง)', 'ไทเก๊ก/ชี่กง', 'วางมือที่ท้องใต้สะดือ หายใจให้ท้องพองยุบ รู้สึกถึงจุดศูนย์กลางร่างกาย 5-10 นาที', 'Jahnke et al. 2010 — รีวิว 66 งานวิจัย Qigong/Tai Chi', 'เดินป่าจังหวะกลาง / วาดภาพ-ปั้นดิน', 'movement/art', 'เดินในจังหวะสม่ำเสมอ ไม่เร่งรีบ 20-30 นาที หรือทำงานศิลปะที่ได้สัมผัสวัสดุจริง (ดินน้ำมัน/สีน้ำ)', 'Art therapy ลดคอร์ติซอลจริง (systematic review, ยอมรับตั้งแต่ 1940s)', 'บ่าย: Dan Tian breathing 5 นาที แล้วเดินเล่นจังหวะช้าๆ 20 นาที — เน้นความรู้สึก ''ปักหลัก'' ตลอดกิจกรรม', 'เช้าหรือบ่าย', 'กิจกรรม grounding เหมาะเป็นช่วงเปลี่ยนผ่าน ไม่จำเป็นต้องผูกกับ circadian phase เท่าธาตุไฟ/น้ำ'),
  ('Wood', 'เมตตาภาวนา (Loving-Kindness Meditation)', 'พุทธ', 'นั่งสบายๆ ระลึกความรู้สึกดีต่อตนเอง แล้วขยายไปยังคนใกล้ตัว 10-15 นาที', 'Lutz et al. 2008, PNAS — กระตุ้น insula + ACC', 'วาดภาพ/เขียนสร้างสรรค์ หรือเล่นดนตรี (ไม่ใช่แค่ฟัง)', 'art/music', 'ให้เวลา 20-30 นาทีทำงานสร้างสรรค์แบบไม่มีเป้าหมายตายตัว ปล่อยให้ไหลไปเรื่อยๆ', 'Music therapy meta-analysis 2022 — ผลบวกต่อ stress-related outcomes', 'กลางวัน: เมตตาภาวนาสั้นๆ 5 นาที แล้วต่อด้วยกิจกรรมสร้างสรรค์อิสระ 20 นาที ไม่ตั้งเป้าผลงาน', 'กลางวัน', 'ธาตุไม้เชื่อมกับการเติบโต/ขยาย เหมาะกับช่วงที่พลังงานกำลังขึ้น ไม่ใช่ต้นหรือปลายวัน'),
  ('Metal', 'Box Breathing (Sama Vritti) / วิปัสสนา', 'โยคะ + พุทธ', 'หายใจเข้า 4 วินาที กลั้น 4 วินาที หายใจออก 4 วินาที กลั้น 4 วินาที ทำ 5-10 รอบ', 'เสถียรภาพระบบประสาทอัตโนมัติ (ANS) — เชื่อมกับหลัก Box Breathing มาตรฐาน', 'งานฝีมือละเอียด/ถ่ายภาพ หรือฟังดนตรีคลาสสิก/มีโครงสร้างชัด', 'art/music', 'เลือกงานที่ต้องใช้ความละเอียด/มีขั้นตอนชัดเจน 20-30 นาที', 'Frontiers 2024 — creative arts เชื่อมกับ medial rPFC ด้าน emotion regulation', 'เย็น: Box Breathing 5 นาทีก่อนเริ่มงานฝีมือ/ถ่ายภาพ 20-30 นาที — เน้นความคมชัด มีโครงสร้าง', 'เย็น', 'ธาตุทองเชื่อมกับความชัดเจน/ปล่อยวาง เหมาะเป็นช่วงสรุปวัน ก่อนเข้าสู่ธาตุน้ำตอนกลางคืน')
